CREATE TABLE lab_teams (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_players (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  team_id INTEGER NOT NULL REFERENCES lab_teams(id)
);

INSERT INTO lab_teams (name) VALUES ('Reds'), ('Blues');
INSERT INTO lab_players (name, team_id)
  SELECT p.name, t.id FROM (VALUES ('Ana', 'Reds'), ('Ben', 'Reds'), ('Chen', 'Blues')) AS p(name, team)
  JOIN lab_teams t ON t.name = p.team;

SELECT p.name AS player, t.name AS team FROM lab_players p JOIN lab_teams t ON t.id = p.team_id ORDER BY p.name;

